insert into customer_project (id, customer_id, name, location, project_type, description, estimated_value, start_date, required_delivery_date, assigned_sales_agent, status, notes, created_at, updated_at) values
('44000000-0000-4000-8000-000000000001', 'e174bba7-b145-5921-99ef-069bda97177d', 'Vasque en pierre naturelle', 'Rabat', 'Salle de bain', 'Conception et pose dune vasque sur mesure en pierre naturelle. Le projet comprend le relevé des cotes, la préparation atelier, le contrôle des finitions et la pose finale.', 28500, DATE '2026-01-12', DATE '2026-02-05', 'Studio UNIVMAR', 'COMPLETED', 'Réception validée. Photo de réalisation archivée.', current_timestamp, current_timestamp),
('44000000-0000-4000-8000-000000000002', '10b9f951-2c29-545c-a2d2-1a25c39c6733', 'Escalier en marbre avec éclairage LED', 'Marrakech', 'Escalier', 'Habillage complet dun escalier contemporain en marbre avec intégration de nez de marche, retombées et éclairage LED. Les joints et alignements ont été contrôlés à la pose.', 96000, DATE '2026-02-03', DATE '2026-03-18', 'Studio UNIVMAR', 'COMPLETED', 'Projet livré et contrôlé avec le maître douvrage.', current_timestamp, current_timestamp),
('44000000-0000-4000-8000-000000000003', 'e174bba7-b145-5921-99ef-069bda97177d', 'Cuisine en granit noir', 'Casablanca', 'Cuisine', 'Fourniture et installation de plans de travail en granit noir pour une cuisine moderne. Le périmètre inclut les découpes évier, les retours, le polissage des chants et la protection finale.', 54000, DATE '2026-03-09', DATE '2026-03-28', 'Studio UNIVMAR', 'COMPLETED', 'Plans de travail livrés avec conseils dentretien.', current_timestamp, current_timestamp),
('44000000-0000-4000-8000-000000000004', '10b9f951-2c29-545c-a2d2-1a25c39c6733', 'Patio en pierre naturelle', 'Témara', 'Extérieur', 'Réalisation dun dallage de patio en pierre naturelle, sélectionné pour sa texture et sa résistance en extérieur. Les pièces ont été calepinées puis posées avec contrôle des pentes.', 73500, DATE '2026-04-06', DATE '2026-04-30', 'Studio UNIVMAR', 'COMPLETED', 'Dallage extérieur terminé et nettoyé avant réception.', current_timestamp, current_timestamp),
('44000000-0000-4000-8000-000000000005', 'e174bba7-b145-5921-99ef-069bda97177d', 'Cheminée en travertin flûté', 'Rabat', 'Intérieur', 'Création dun habillage de cheminée en travertin flûté avec modules découpés sur mesure. La composition met en valeur le veinage de la pierre et les proportions du séjour.', 46800, DATE '2026-05-11', DATE '2026-05-29', 'Studio UNIVMAR', 'COMPLETED', 'Finitions et protection de surface validées.', current_timestamp, current_timestamp);
